//! Caller metadata, phase B: the readable manifest in `LocationProof` field 19.
//!
//! `test-vectors/caller-metadata/field19.json` pins the encoded `CallerManifest`
//! bytes and the `caller-manifest` result per vector, for the SDKs' encoders to
//! test against. The vectors were generated by an independent encoder; here
//! prost rebuilds every message from its listed entries and must produce the
//! same bytes. A signed synthetic proof then exercises `verify()` end to end.

use std::fs;
use std::process::Command;

use octet_verify::caller_metadata::{
    self as cm, check_caller_manifest, check_caller_metadata, check_manifest_locators, CallerManifest,
    CallerMetadataInputs, CallerMetadataOutcome, Content, ManifestEntry,
};
use octet_verify::crypto::sha256;
use octet_verify::navigate::{
    CallerManifest as Field19, CallerManifestEntry, DeviceAttestation, LocationProof, StageAttestation,
};
use octet_verify::prost::Message;
use octet_verify::verify::{verify, Report, Status, VerifyOptions};
use p256::ecdsa::{signature::Signer, Signature, SigningKey};
use serde_json::Value;

const DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/test-vectors/caller-metadata");
const BIN: &str = env!("CARGO_BIN_EXE_octet-verify");

fn doc() -> Value {
    serde_json::from_str(&fs::read_to_string(format!("{DIR}/field19.json")).unwrap()).unwrap()
}

fn field19_of(v: &Value) -> Field19 {
    Field19 {
        entries: v["field19"]
            .as_array()
            .unwrap()
            .iter()
            .map(|e| CallerManifestEntry {
                key: e["key"].as_str().unwrap().into(),
                content_type: e["contentType"].as_str().unwrap().into(),
                size: e["size"].as_u64().unwrap(),
                sha256: hex::decode(e["sha256"].as_str().unwrap()).unwrap(),
                locator: e["locator"].as_str().unwrap().into(),
            })
            .collect(),
    }
}

/// The presenter manifest, built by hand so this runs without the
/// `caller-metadata` feature (which only adds the JSON parser).
fn presenter_of(v: &Value) -> Option<CallerManifest> {
    let p = v.get("presenter_manifest").filter(|p| !p.is_null())?;
    Some(CallerManifest {
        entries: p["entries"]
            .as_array()
            .unwrap()
            .iter()
            .map(|e| ManifestEntry {
                key: e["key"].as_str().unwrap().into(),
                content_type: e["contentType"].as_str().unwrap().into(),
                size: e["size"].as_u64().unwrap(),
                salt: hex::decode(e["salt"].as_str().unwrap()).unwrap(),
                entry_digest: hex::decode(e["sha256"].as_str().unwrap()).unwrap().try_into().unwrap(),
            })
            .collect(),
    })
}

fn bare_proof(v: &Value, field: Field19) -> LocationProof {
    let stages = match v["stage_data_hash"].as_str() {
        Some(h) => vec![StageAttestation {
            stage: cm::CALLER_METADATA_STAGE.into(),
            timestamp_ms: 1,
            data_hash: hex::decode(h).unwrap(),
            signature: vec![],
            previous_hash: None,
        }],
        None => vec![],
    };
    LocationProof { stage_attestations: stages, caller_manifest: Some(field), ..Default::default() }
}

#[test]
fn field19_vectors() {
    let d = doc();
    let vectors = d["vectors"].as_array().unwrap();
    assert_eq!(vectors.len(), 21);
    for v in vectors {
        let name = v["name"].as_str().unwrap();
        let field = field19_of(v);

        // The bytes: prost encodes the listed entries exactly as pinned, and
        // decodes the pinned bytes back to them.
        let pinned = hex::decode(v["caller_manifest_hex"].as_str().unwrap()).unwrap();
        assert_eq!(field.encode_to_vec(), pinned, "{name}: encoding");
        assert_eq!(Field19::decode(&*pinned).unwrap(), field, "{name}: decoding");

        // Every committed item's digest is SHA256(salt ‖ value).
        for s in v["source"].as_array().unwrap() {
            let mut buf = hex::decode(s["salt_hex"].as_str().unwrap()).unwrap();
            buf.extend(hex::decode(s["value_hex"].as_str().unwrap()).unwrap());
            let digest = sha256(&buf);
            if v["expected"] == "PASS" {
                let e = field.entries.iter().find(|e| e.key == s["key"].as_str().unwrap()).unwrap();
                assert_eq!(e.sha256, digest.to_vec(), "{name}: {} digest", e.key);
            }
        }

        let proof = bare_proof(v, field);
        let presenter = presenter_of(v);
        let c = check_caller_manifest(&proof, presenter.as_ref());
        match v["expected"].as_str().unwrap() {
            "PASS" => assert_eq!(c.status, Status::Pass, "{name}: {}", c.detail),
            code => {
                assert_eq!(c.status, Status::Fail, "{name}: {}", c.detail);
                assert!(c.detail.starts_with(&format!("{code}: ")), "{name}: {}", c.detail);
            }
        }
        let warn = check_manifest_locators(&proof);
        assert_eq!(warn.is_some(), v["locator_warning"].as_bool().unwrap(), "{name}: locator warning");
        if let Some(w) = warn {
            assert_eq!((w.name, w.status), ("caller-manifest-locator", Status::Warn));
        }

        // A presenter manifest that disagrees with field 19 is MANIFEST_MISMATCH
        // on the caller-metadata check too, before any content is looked at.
        if name == "presenter_manifest_differs" {
            let r = check_caller_metadata(&proof, &CallerMetadataInputs { manifest: Some(Ok(presenter.unwrap())), ..Default::default() });
            assert_eq!(r.outcome, CallerMetadataOutcome::ManifestMismatch, "{}", r.check.detail);
        }
    }
}

// --- a signed synthetic proof, end to end --------------------------------------

fn signed_stage(sk: &SigningKey, name: &str, data: &[u8], ts: i64, prev: Option<Vec<u8>>) -> StageAttestation {
    let data_hash = sha256(data).to_vec();
    let mut m = Vec::new();
    m.extend_from_slice(name.as_bytes());
    m.extend_from_slice(&data_hash);
    m.extend_from_slice(&ts.to_be_bytes());
    if let Some(p) = &prev {
        m.extend_from_slice(p);
    }
    let sig: Signature = sk.sign(&m);
    StageAttestation { stage: name.into(), timestamp_ms: ts, data_hash, signature: sig.to_bytes().to_vec(), previous_hash: prev }
}

const NOTE: &[u8] = b"Delivered to the front door.";
const SALT: [u8; 32] = [0x5A; 32];
const PHOTO: &[u8] = &[0xD8; 4096];

fn manifest() -> CallerManifest {
    let e = |key: &str, ct: &str, v: &[u8], salt: &[u8]| ManifestEntry {
        key: key.into(),
        content_type: ct.into(),
        size: v.len() as u64,
        salt: salt.to_vec(),
        entry_digest: cm::entry_digest(salt, v),
    };
    CallerManifest { entries: vec![e("note", "text/plain", NOTE, &SALT), e("photo", "image/jpeg", PHOTO, &[])] }
}

fn field19(m: &CallerManifest, locator: &str) -> Field19 {
    Field19 {
        entries: m
            .entries
            .iter()
            .map(|e| CallerManifestEntry {
                key: e.key.clone(),
                content_type: e.content_type.clone(),
                size: e.size,
                sha256: e.entry_digest.to_vec(),
                locator: locator.into(),
            })
            .collect(),
    }
}

/// (proof carrying the stage and field 19, SEC1 key). Field 19 sits outside
/// every stage, so it is attached after signing.
fn signed_proof(locator: &str) -> (LocationProof, Vec<u8>) {
    let sk = SigningKey::from_slice(&[7u8; 32]).unwrap();
    let (commitment, nullifier) = (vec![0xC0u8; 32], vec![0x1Au8; 32]);
    let s0 = signed_stage(&sk, "spoofDetection", b"verdict", 0, None);
    let s1 = signed_stage(&sk, cm::CALLER_METADATA_STAGE, &manifest().preimage().unwrap(), 0, Some(s0.data_hash.clone()));
    let s2 = signed_stage(&sk, "commitment", &commitment, 0, Some(s1.data_hash.clone()));
    let s3 = signed_stage(&sk, "nullifier", &nullifier, 0, Some(s2.data_hash.clone()));
    let concat: Vec<u8> = [&s0, &s1, &s2, &s3].iter().flat_map(|s| s.signature.clone()).collect();
    let asm = signed_stage(&sk, "proofAssembly", &concat, 0, Some(s3.data_hash.clone()));
    let proof = LocationProof {
        id: "caller-manifest".into(),
        position_commitment: commitment,
        nullifier,
        timestamp_ms: 0,
        device_attestation: Some(DeviceAttestation::default()),
        stage_attestations: vec![s0, s1, s2, s3, asm],
        platform: "ios".into(),
        caller_manifest: Some(field19(&manifest(), locator)),
        ..Default::default()
    };
    (proof, sk.verifying_key().to_encoded_point(false).as_bytes().to_vec())
}

fn core_report(proof: &LocationProof, sec1: &[u8]) -> Report {
    let vk = octet_verify::crypto::P256VerifyingKey::from_sec1_bytes(sec1).unwrap();
    verify(proof, &VerifyOptions {
        now_ms: 0,
        max_age_s: 999_999_999_999,
        hardware_pubkey: Some(&vk),
        hw_key_source: "test",
        expect_region: None,
        expect_region_type: None,
        expect_region_contains: None,
        session_nonce: None,
        require_session_binding: false,
        require_schema_v2: false,
        require_attestation: false,
        require_verdict: None,
        validation_window: None,
    })
}

fn failing(r: &Report) -> String {
    r.checks.iter().filter(|c| c.status != Status::Pass).map(|c| format!("{}: {}", c.name, c.detail)).collect::<Vec<_>>().join("; ")
}

fn line<'a>(r: &'a Report, name: &str) -> Option<&'a octet_verify::verify::Check> {
    r.checks.iter().find(|c| c.name == name)
}

#[test]
fn verify_adds_the_caller_manifest_line_only_for_field19() {
    let (proof, sec1) = signed_proof("obj_01HZX4QK9T7M3");
    let r = core_report(&proof, &sec1);
    let c = line(&r, "caller-manifest").expect("a proof with field 19 gets the line");
    assert_eq!(c.status, Status::Pass, "{}", c.detail);
    assert!(c.detail.contains("locator hint"), "{}", c.detail);
    assert!(r.is_authentic(), "{}", failing(&r));
    assert_eq!(r.caller_manifest().unwrap().entries.len(), 2);
    assert!(line(&r, "caller-manifest-locator").is_none());

    // Without field 19 there is no new line, so existing reports are unchanged.
    let mut without = proof.clone();
    without.caller_manifest = None;
    let r = core_report(&without, &sec1);
    assert!(line(&r, "caller-manifest").is_none());
    assert!(r.caller_manifest().is_none());
    assert!(r.is_authentic());
}

#[test]
fn an_edited_field19_fails_and_a_credential_locator_only_warns() {
    let (mut proof, sec1) = signed_proof("");
    // Edit a digest after signing: the stage no longer matches.
    proof.caller_manifest.as_mut().unwrap().entries[1].sha256[0] ^= 1;
    let r = core_report(&proof, &sec1);
    let c = line(&r, "caller-manifest").unwrap();
    assert!(c.status == Status::Fail && c.detail.starts_with("MANIFEST_MISMATCH: "), "{}", c.detail);
    assert!(!r.is_valid());
    assert!(r.caller_manifest().is_none(), "an unmatched field 19 is not exposed");

    // A credential-shaped locator: still VALID, plus a WARN that does not make
    // content unresolved.
    let (proof, sec1) = signed_proof("https://files.example/p.jpg?X-Amz-Signature=1");
    let r = core_report(&proof, &sec1);
    assert_eq!(line(&r, "caller-manifest").unwrap().status, Status::Pass);
    assert_eq!(line(&r, "caller-manifest-locator").unwrap().status, Status::Warn);
    assert!(r.content_resolved() && r.is_authentic(), "{}", failing(&r));
}

#[test]
fn presenter_content_checks_against_a_proof_with_field19() {
    let (proof, _) = signed_proof("");
    let content = || vec![("note".to_string(), Content::Bytes(NOTE)), ("photo".to_string(), Content::Bytes(PHOTO))];
    let r = check_caller_metadata(&proof, &CallerMetadataInputs { manifest: Some(Ok(manifest())), content: content(), ..Default::default() });
    assert_eq!((r.outcome, r.by_content), (CallerMetadataOutcome::Verified, 2), "{}", r.check.detail);

    // The presenter swaps the order: field 19 disagrees, so MANIFEST_MISMATCH.
    let mut swapped = manifest();
    swapped.entries.reverse();
    let r = check_caller_metadata(&proof, &CallerMetadataInputs { manifest: Some(Ok(swapped)), content: content(), ..Default::default() });
    assert_eq!(r.outcome, CallerMetadataOutcome::ManifestMismatch, "{}", r.check.detail);
}

#[test]
fn a_duplicated_field19_is_refused_on_the_wire() {
    let (proof, sec1) = signed_proof("");
    let dir = std::env::temp_dir().join(format!("octet-verify-f19-{}", std::process::id()));
    fs::create_dir_all(&dir).unwrap();
    let mut bytes = proof.encode_to_vec();
    // Append a second field 19 (tag 0x9a 0x01, wire type 2) carrying one more entry:
    // prost would merge it into the first.
    let extra = Field19 { entries: field19(&manifest(), "").entries[..1].to_vec() }.encode_to_vec();
    bytes.extend_from_slice(&[0x9a, 0x01]);
    bytes.push(extra.len() as u8);
    bytes.extend_from_slice(&extra);
    fs::write(dir.join("proof.bin"), &bytes).unwrap();
    fs::write(dir.join("hw.pubkey"), &sec1).unwrap();
    let out = Command::new(BIN)
        .arg(dir.join("proof.bin"))
        .args(["--hardware-pubkey", dir.join("hw.pubkey").to_str().unwrap(), "--max-age-seconds", "999999999999"])
        .output()
        .unwrap();
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert_eq!(out.status.code(), Some(1), "{stdout}");
    assert!(stdout.contains("caller_manifest (field 19)"), "{stdout}");
    let _ = fs::remove_dir_all(&dir);
}

#[test]
fn cli_json_carries_the_matched_manifest() {
    let (proof, sec1) = signed_proof("obj_1");
    let dir = std::env::temp_dir().join(format!("octet-verify-f19-json-{}", std::process::id()));
    fs::create_dir_all(&dir).unwrap();
    fs::write(dir.join("proof.bin"), proof.encode_to_vec()).unwrap();
    fs::write(dir.join("hw.pubkey"), &sec1).unwrap();
    let run = |p: &str| {
        let out = Command::new(BIN)
            .arg(dir.join(p))
            .args(["--hardware-pubkey", dir.join("hw.pubkey").to_str().unwrap(), "--max-age-seconds", "999999999999", "--json"])
            .output()
            .unwrap();
        (out.status.code(), serde_json::from_slice::<Value>(&out.stdout).unwrap())
    };
    let (code, j) = run("proof.bin");
    assert_eq!(code, Some(0), "{j}");
    let entries = j["caller_manifest"].as_array().unwrap();
    assert_eq!(entries.len(), 2);
    assert_eq!(entries[0]["key"], "note");
    assert_eq!(entries[0]["sha256"], hex::encode(cm::entry_digest(&SALT, NOTE)));
    assert_eq!(entries[1]["size"], 4096);
    assert_eq!(entries[1]["locator"], "obj_1");

    let mut plain = proof.clone();
    plain.caller_manifest = None;
    fs::write(dir.join("plain.bin"), plain.encode_to_vec()).unwrap();
    assert!(run("plain.bin").1["caller_manifest"].is_null());
    let _ = fs::remove_dir_all(&dir);
}
